/* Fashion preview polish: image-led discovery, restrained motion and depth */
.hf-fashion{overflow:hidden;--fashion-ease:cubic-bezier(.2,.7,.2,1)}
.hf-fashion-hero{min-height:440px;isolation:isolate}
.hf-fashion-hero>img{transition:transform 1.2s var(--fashion-ease);will-change:transform}
.hf-fashion-hero:hover>img{transform:scale(1.035)}
.hf-fashion-hero-overlay{position:absolute;inset:0;background:linear-gradient(90deg,rgba(18,17,16,.34),rgba(18,17,16,.02) 68%);pointer-events:none}
.hf-fashion-hero-copy{box-shadow:0 24px 70px rgba(30,24,20,.12);animation:hfFashionRise .8s var(--fashion-ease) both}
.hf-fashion-hero-copy button,.hf-fashion-bag,.hf-fashion-nav button,.hf-fashion-collection,.hf-fashion-product-grid .hf-shop-add{transition:transform .28s var(--fashion-ease),background-color .28s ease,color .28s ease,box-shadow .28s ease}
.hf-fashion-hero-copy button:hover{transform:translateY(-3px);box-shadow:0 12px 26px rgba(0,0,0,.18)}
.hf-fashion-nav button{position:relative;padding:6px 0}
.hf-fashion-nav button:after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1px;background:currentColor;transition:right .25s ease}
.hf-fashion-nav button:hover:after{right:0}
.hf-fashion-hero-caption{position:absolute;left:4%;bottom:18px;z-index:2;color:#fff;font-size:9px;font-weight:800;letter-spacing:.2em;text-shadow:0 2px 12px rgba(0,0,0,.45)}
.hf-fashion-collections{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.hf-fashion-collection{position:relative;isolation:isolate;overflow:hidden;min-height:220px;padding:16px;color:#fff;background:#34302d;box-shadow:0 8px 24px rgba(30,24,20,.08);transform-style:preserve-3d}
.hf-fashion-collection img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;transition:transform .8s var(--fashion-ease),filter .5s ease}
.hf-fashion-collection-shade{position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.58))}
.hf-fashion-collection-index{font-size:10px;letter-spacing:.12em}
.hf-fashion-collection strong{font-family:var(--sf-display,"Cormorant Garamond",serif);font-size:clamp(19px,2vw,28px);text-shadow:0 2px 12px rgba(0,0,0,.35)}
.hf-fashion-collection small{font-size:9px}
.hf-fashion-collection:hover{transform:translateY(-5px) rotateX(1.5deg);box-shadow:0 18px 38px rgba(30,24,20,.18)}
.hf-fashion-collection:hover img{transform:scale(1.09);filter:saturate(1.12)}
.hf-fashion-product-grid .hf-shop-product{transition:transform .35s var(--fashion-ease),box-shadow .35s ease}
.hf-fashion-product-grid .hf-shop-product:hover{transform:translateY(-6px);box-shadow:0 18px 34px rgba(34,29,25,.09)}
.hf-fashion-product-grid .hf-shop-product-image img{transition:transform .7s var(--fashion-ease),filter .4s ease}
.hf-fashion-product-grid .hf-shop-product:hover .hf-shop-product-image img{transform:scale(1.065);filter:saturate(1.05)}
.hf-fashion-product-grid .hf-shop-add:hover{transform:scale(1.12) rotate(90deg)}
.hf-fashion-products-foot{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:20px 0 2px;border-top:1px solid #e7e0d7;font-size:10px;color:#71685f}
.hf-fashion-products-foot a,.hf-fashion-journal-head a{font-weight:800;text-decoration:underline;text-underline-offset:4px}
.hf-fashion-story{overflow:hidden}
.hf-fashion-story img{transition:transform .9s var(--fashion-ease);box-shadow:0 18px 44px rgba(30,24,20,.12)}
.hf-fashion-story:hover img{transform:scale(1.035) rotate(.4deg)}
.hf-fashion-journal{padding:38px 4%;background:#f7f4ef}
.hf-fashion-journal-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}
.hf-fashion-journal-card{background:#fffdfa;min-width:0;transition:transform .35s var(--fashion-ease),box-shadow .35s ease}
.hf-fashion-journal-card:hover{transform:translateY(-5px);box-shadow:0 16px 36px rgba(30,24,20,.1)}
.hf-fashion-journal-image{height:220px;position:relative;overflow:hidden;background:#e8e0d7}
.hf-fashion-journal-image img{width:100%;height:100%;object-fit:cover;transition:transform .8s var(--fashion-ease)}
.hf-fashion-journal-card:hover .hf-fashion-journal-image img{transform:scale(1.06)}
.hf-fashion-journal-image span{position:absolute;left:12px;top:12px;background:rgba(255,253,250,.9);padding:6px 8px;font-size:9px}
.hf-fashion-journal-copy{padding:16px}
.hf-fashion-journal-copy small{font-size:9px;letter-spacing:.13em;font-weight:800;color:#907a68}
.hf-fashion-journal-copy h4{font-family:"Cormorant Garamond",serif;font-size:24px;line-height:1.05;margin:9px 0}
.hf-fashion-journal-copy p{font-size:11px;line-height:1.65;color:#6d655d}
.hf-fashion-journal-copy a{font-size:10px;font-weight:800;text-decoration:underline;text-underline-offset:4px}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection{border:1px solid rgba(23,25,29,.16)}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(10,12,15,.05),rgba(10,12,15,.75))}
.hf-fashion--streetwear-sneaker-store .hf-fashion-collection strong{font-family:"Space Grotesk",sans-serif;text-transform:uppercase}
.hf-fashion--boutique-ethnic-wear .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(47,30,24,.08),rgba(47,30,24,.65))}
.hf-fashion--fashion-retailer .hf-fashion-collection-shade{background:linear-gradient(180deg,rgba(28,48,55,.06),rgba(28,48,55,.68))}
@keyframes hfFashionRise{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.hf-fashion *, .hf-fashion *:before,.hf-fashion *:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
@media(max-width:700px){.hf-fashion-hero{min-height:420px}.hf-fashion-collections{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.hf-fashion-collection{min-height:175px;padding:12px}.hf-fashion-journal-grid{grid-template-columns:1fr;gap:12px}.hf-fashion-journal-image{height:230px}.hf-fashion-products-foot{align-items:flex-start;flex-direction:column}}

