cover{padding:24px 5% 36px}.hf-restaurant-preview-discover h3{font-family:Georgia,serif;font-size:26px;font-weight:500}.hf-restaurant-preview-discover>div{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.hf-restaurant-preview-card{background:#fff;padding-bottom:14px}.hf-restaurant-preview-card img{width:100%;height:115px;object-fit:cover}.hf-restaurant-preview-card small,.hf-restaurant-preview-card h3,.hf-restaurant-preview-card p{margin-left:12px;margin-right:12px}.hf-restaurant-preview-card small{display:block;margin-top:10px;color:var(--rp-accent);font-size:8px}.hf-restaurant-preview-card h3{font-size:14px;margin-top:6px;margin-bottom:4px}.hf-restaurant-preview-card p{font-size:10px;line-height:1.5;color:#687078}.hf-restaurant-preview footer{display:flex;justify-content:space-between;gap:14px;padding:18px 5%;border-top:1px solid rgba(0,0,0,.12);font-size:9px;color:#687078}@media(max-width:680px){.hf-restaurant-preview-hero{grid-template-columns:1fr}.hf-restaurant-preview header nav{display:none}.hf-restaurant-preview-discover>div{grid-template-columns:1fr 1fr}.hf-restaurant-preview footer{display:block}}

/* Education & Training — four independently art-directed previews */
.hf-edu-preview{--edu-ink:#20344a;--edu-paper:#f8f5ec;--edu-accent:#d4a63b;background:var(--edu-paper);color:var(--edu-ink);font-family:"DM Sans",Inter,sans-serif;overflow:hidden}
.hf-edu-preview--veridian-university{--edu-ink:#24243a;--edu-paper:#f5f2f7;--edu-accent:#6c4c8c;font-family:"Manrope",Inter,sans-serif}
.hf-edu-preview--forge-skills-institute{--edu-ink:#202329;--edu-paper:#f4f2ed;--edu-accent:#f06a3a;font-family:"Space Grotesk",Inter,sans-serif}
.hf-edu-preview--brightpath-tutoring{--edu-ink:#343047;--edu-paper:#fbf5f0;--edu-accent:#d66c75;font-family:"Manrope",Inter,sans-serif}
.hf-edu-topline{padding:10px 5%;background:var(--edu-ink);color:#fff;font-size:9px;letter-spacing:.15em;display:flex;justify-content:space-between}
.hf-edu-topline span{opacity:.72;letter-spacing:.04em}
.hf-edu-header{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:22px 5%;border-bottom:1px solid color-mix(in srgb,var(--edu-ink) 12%,transparent)}
.hf-edu-brand{font-weight:900;letter-spacing:.09em;color:var(--edu-ink);text-decoration:none;font-size:16px}
.hf-edu-brand span{font-weight:500;letter-spacing:.02em}
.hf-edu-header nav{display:flex;gap:18px;flex-wrap:wrap}
.hf-edu-header nav a{font-size:11px;color:var(--edu-ink);text-decoration:none}
.hf-edu-header>button,.hf-edu-hero-copy button,.hf-edu-cta button{border:0;border-radius:3px;padding:13px 18px;background:var(--edu-ink);color:white;font-weight:700;font-size:11px;cursor:pointer}
.hf-edu-hero{display:grid;grid-template-columns:1fr .92fr;min-height:410px;padding:54px 6%;gap:36px;align-items:center}
.hf-edu-hero-copy>small,.hf-edu-feature small,.hf-edu-courses small,.hf-edu-cta small{font-size:9px;font-weight:800;letter-spacing:.17em;color:var(--edu-accent)}
.hf-edu-hero h2{font-family:"Cormorant Garamond",Georgia,serif;font-size:clamp(38px,5vw,68px);line-height:.98;letter-spacing:-.035em;max-width:570px;margin:18px 0}
.hf-edu-preview--veridian-university .hf-edu-hero h2{font-family:"Playfair Display",Georgia,serif;font-size:clamp(36px,4.5vw,60px)}
.hf-edu-preview--forge-skills-institute .hf-edu-hero h2{font-family:"Space Grotesk",sans-serif;font-weight:700;letter-spacing:-.065em}
.hf-edu-preview--brightpath-tutoring .hf-edu-hero h2{font-family:"Cormorant Garamond",Georgia,serif}
.hf-edu-hero-copy>p{font-size:13px;line-height:1.8;max-width:480px;opacity:.8}
.hf-edu-hero-copy>div:nth-of-type(1){display:flex;align-items:center;gap:20px;margin-top:24px}
.hf-edu-hero-copy>div:nth-of-type(1) a{font-size:11px;color:var(--edu-ink);font-weight:700}
.hf-edu-proof{display:flex;gap:12px;flex-wrap:wrap;margin-top:30px}
.hf-edu-proof span{font-size:9px;opacity:.75}
.hf-edu-hero-art{position:relative}
.hf-edu-hero-art img{width:100%;display:block;aspect-ratio:1.25;object-fit:cover;border-radius:2px}
.hf-edu-hero-art>span{position:absolute;bottom:12px;left:14px;background:var(--edu-paper);padding:7px 10px;font-size:8px;letter-spacing:.13em}
.hf-edu-stats{display:grid;grid-template-columns:repeat(3,1fr);background:var(--edu-ink);color:white;padding:28px 7%;gap:20px}
.hf-edu-stats>div{display:flex;align-items:center;gap:14px;border-right:1px solid #ffffff30}
.hf-edu-stats>div:last-child{border:0}
.hf-edu-stats b{font:600 25px Georgia;color:var(--edu-accent)}
.hf-edu-stats span{font-size:11px;opacity:.8}
.hf-edu-feature{display:grid;grid-template-columns:1fr .75fr;gap:40px;align-items:center;padding:70px 8%}
.hf-edu-feature h3,.hf-edu-courses h3,.hf-edu-cta h3{font:600 clamp(28px,3.5vw,44px)/1.1 "Cormorant Garamond",Georgia,serif;margin:12px 0}
.hf-edu-feature p{font-size:13px;line-height:1.8;max-width:540px;opacity:.78}
.hf-edu-feature img{width:100%;aspect-ratio:1.3;object-fit:cover}
.hf-edu-courses{padding:58px 7%;background:color-mix(in srgb,var(--edu-accent) 8%,var(--edu-paper))}
.hf-edu-course-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:28px}
.hf-edu-course-grid article{padding:20px;background:white;border:1px solid color-mix(in srgb,var(--edu-ink) 10%,transparent);min-height:180px}
.hf-edu-course-grid article>span{font-size:10px;color:var(--edu-accent);font-weight:800}
.hf-edu-course-grid h4{font:600 19px Georgia;margin:18px 0 8px}
.hf-edu-course-grid p{font-size:11px;line-height:1.65;opacity:.75}
.hf-edu-course-grid a{font-size:10px;font-weight:800;color:var(--edu-ink)}
.hf-edu-cta{display:flex;justify-content:space-between;align-items:center;gap:25px;padding:54px 7%;background:var(--edu-accent);color:var(--edu-ink)}
.hf-edu-cta small{color:var(--edu-ink)}
.hf-edu-cta h3{margin:10px 0}
.hf-edu-cta p{font-size:12px;max-width:540px;line-height:1.7}
.hf-edu-cta button{background:var(--edu-ink);white-space:nowrap}
.hf-edu-footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:25px 6%;background:var(--edu-ink);color:white;font-size:10px}
.hf-edu-footer span{opacity:.7}
.hf-edu-preview--forge-skills-institute .hf-edu-hero{background:var(--edu-ink);color:white}
.hf-edu-preview--forge-skills-institute .hf-edu-hero-copy>div:nth-of-type(1) a{color:white}
.hf-edu-preview--forge-skills-institute .hf-edu-hero-art img{filter:saturate(.75) contrast(1.08)}
.hf-edu-preview--veridian-university .hf-edu-stats{background:#302c48}
.hf-edu-preview--brightpath-tutoring .hf-edu-course-grid article{border-radius:14px;box-shadow:0 10px 30px #3430470c}
.hf-edu-preview--brightpath-tutoring .hf-edu-hero-art img{border-radius:30px 30px 30px 4px}
@media(max-width:760px){.hf-edu-header{align-items:flex-start;flex-wrap:wrap}.hf-edu-header nav{order:3;width:100%;gap:12px}.hf-edu-header>button{margin-left:auto}.hf-edu-hero,.hf-edu-feature{grid-template-columns:1fr;padding:34px 6%;gap:22px}.hf-edu-hero h2{font-size:42px}.hf-edu-stats{padding:20px 6%;gap:8px}.hf-edu-stats>div{display:block;padding-right:8px}.hf-edu-stats b{display:block;font-size:21px}.hf-edu-stats span{font-size:9px}.hf-edu-course-grid{grid-template-columns:repeat(2,1fr)}.hf-edu-cta{align-items:flex-start;flex-direction:column}.hf-edu-topline span{display:none}}
@media(max-width:420px){.hf-edu-course-grid{grid-template-columns:1fr}.hf-edu-hero-copy>div:nth-of-type(1){align-items:flex-start;flex-direction:column;gap:12px}}

/* Beauty & Salon — four independent preview identities */
.hf-beauty-preview{--beauty-paper:#f6eee8;--beauty-ink:#302a29;--beauty-accent:#8d5d54;--beauty-soft:#e8d7ce;background:var(--beauty-paper);color:var(--beauty-ink);min-height:680px;overflow:hidden;font-family:"DM Sans",Arial,sans-serif}
.hf-beauty-topline{padding:12px 4.5%;font-size:9px;letter-spacing:.2em;font-weight:800;border-bottom:1px solid currentColor;border-color:color-mix(in srgb,var(--beauty-ink) 18%,transparent)}
.hf-beauty-preview>header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px 4.5%;border-bottom:1px solid color-mix(in srgb,var(--beauty-ink) 15%,transparent)}
.hf-beauty-preview>header strong{font:700 23px "Cormorant Garamond",Georgia,serif;letter-spacing:.1em}
.hf-beauty-preview>header nav{display:flex;gap:20px;flex-wrap:wrap}
.hf-beauty-preview>header nav span{font-size:10px;color:color-mix(in srgb,var(--beauty-ink) 72%,transparent)}
.hf-beauty-preview>header>b{font-size:9px;letter-spacing:.12em;border-bottom:1px solid var(--beauty-accent);padding-bottom:7px}
.hf-beauty-hero{display:grid;grid-template-columns:1fr .92fr;gap:5%;align-items:center;padding:54px 6% 50px}
.hf-beauty-hero-copy>small,.hf-beauty-section-head>small,.hf-beauty-cta small{font-size:9px;letter-spacing:.2em;font-weight:800;color:var(--beauty-accent)}
.hf-beauty-hero h2{font:500 clamp(38px,5.5vw,70px)/.98 "Cormorant Garamond",Georgia,serif;letter-spacing:-.035em;max-width:620px;margin:18px 0}
.hf-beauty-hero p{max-width:480px;font-size:13px;line-height:1.8;color:color-mix(in srgb,var(--beauty-ink) 76%,transparent)}
.hf-beauty-hero-copy>div:first-of-type{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}
.hf-beauty-hero-copy>div:first-of-type a{display:inline-flex;padding:13px 17px;background:var(--beauty-accent);color:#fff;text-decoration:none;font-size:10px;letter-spacing:.04em}
.hf-beauty-hero-copy>div:first-of-type a.is-secondary{background:transparent;color:var(--beauty-ink);border:1px solid color-mix(in srgb,var(--beauty-ink) 30%,transparent)}
.hf-beauty-promises{display:flex;gap:16px;flex-wrap:wrap;margin-top:28px}
.hf-beauty-promises span{font-size:9px;color:color-mix(in srgb,var(--beauty-ink) 68%,transparent)}
.hf-beauty-hero-image{position:relative;min-height:360px;max-height:460px;overflow:hidden;background:var(--beauty-soft)}
.hf-beauty-hero-image img{display:block;width:100%;height:100%;min-height:360px;max-height:460px;object-fit:cover}
.hf-beauty-hero-image span{position:absolute;left:18px;bottom:18px;color:var(--beauty-ink);background:var(--beauty-paper);padding:9px 12px;font-size:8px;letter-spacing:.16em}
.hf-beauty-services{padding:42px 6% 58px}
.hf-beauty-section-head{max-width:650px;margin:0 auto 28px;text-align:center}
.hf-beauty-section-head h3{font:500 clamp(28px,4vw,43px)/1.08 "Cormorant Garamond",Georgia,serif;margin:10px 0}
.hf-beauty-section-head p{font-size:12px;line-height:1.7;opacity:.72}
.hf-beauty-service-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.hf-beauty-service{min-width:0;background:color-mix(in srgb,var(--beauty-paper) 76%,white);padding:0 0 18px;border:1px solid color-mix(in srgb,var(--beauty-ink) 12%,transparent)}
.hf-beauty-service img{display:block;width:100%;aspect-ratio:1.25;object-fit:cover;background:var(--beauty-soft)}
.hf-beauty-service small,.hf-beauty-service h3,.hf-beauty-service p,.hf-beauty-service span{display:block;margin-left:16px;margin-right:16px}
.hf-beauty-service small{margin-top:16px;font-size:8px;letter-spacing:.15em;color:var(--beauty-accent)}
.hf-beauty-service h3{font:600 19px "Cormorant Garamond",Georgia,serif;margin-top:8px;margin-bottom:6px}
.hf-beauty-service p{font-size:10px;line-height:1.65;opacity:.72}
.hf-beauty-service span{font-size:9px;font-weight:800;color:var(--beauty-accent);margin-top:14px}
.hf-beauty-cta{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:28px 6%;background:var(--beauty-ink);color:#fff}
.hf-beauty-cta h3{font:500 30px "Cormorant Garamond",Georgia,serif;margin:7px 0}
.hf-beauty-cta p{font-size:11px;opacity:.76;max-width:560px}
.hf-beauty-cta a{color:#fff;border:1px solid #ffffff70;padding:12px 16px;text-decoration:none;font-size:10px;white-space:nowrap}
.hf-beauty-preview>footer{display:flex;justify-content:space-between;gap:18px;padding:20px 6%;font-size:9px;opacity:.7}
.hf-beauty-preview--the-hair-atelier{--beauty-paper:#f0eee8;--beauty-ink:#202324;--beauty-accent:#b75b3a;--beauty-soft:#dccabd}
.hf-beauty-preview--the-hair-atelier .hf-beauty-topline{background:#202324;color:#f0eee8}
.hf-beauty-preview--the-hair-atelier>header{background:#202324;color:#f0eee8;border:0}
.hf-beauty-preview--the-hair-atelier>header strong{font:700 18px "Space Grotesk",sans-serif;letter-spacing:.12em}
.hf-beauty-preview--the-hair-atelier .hf-beauty-hero{grid-template-columns:1.1fr .9fr;padding-top:38px}
.hf-beauty-preview--the-hair-atelier .hf-beauty-hero h2{font:700 clamp(40px,6vw,76px)/.92 "Space Grotesk",sans-serif;letter-spacing:-.07em;text-transform:uppercase}
.hf-beauty-preview--the-hair-atelier .hf-beauty-hero-image{border-radius:0 0 100px 0}
.hf-beauty-preview--the-hair-atelier .hf-beauty-service{border:0;background:#e6e1d8}
.hf-beauty-preview--forme-nail-brow{--beauty-paper:#f4eff4;--beauty-ink:#3b303c;--beauty-accent:#a66a83;--beauty-soft:#e4d5e3}
.hf-beauty-preview--forme-nail-brow .hf-beauty-topline{text-align:center}
.hf-beauty-preview--forme-nail-brow>header{justify-content:center;flex-direction:column;gap:10px}
.hf-beauty-preview--forme-nail-brow>header strong{font:700 28px "Space Grotesk",sans-serif;letter-spacing:.2em}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero{grid-template-columns:1fr;max-width:940px;margin:auto;text-align:center}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero-copy{max-width:740px;margin:auto}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero h2{font:500 clamp(38px,5vw,64px)/1.02 "Playfair Display",Georgia,serif}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero-copy>div:first-of-type,.hf-beauty-preview--forme-nail-brow .hf-beauty-promises{justify-content:center}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero-image{max-width:560px;width:100%;min-height:260px;margin:auto;border-radius:46% 46% 10px 10px}
.hf-beauty-preview--forme-nail-brow .hf-beauty-hero-image img{min-height:260px}
.hf-beauty-preview--forme-nail-brow .hf-beauty-service{border-radius:18px;overflow:hidden;background:#fffafd;border:1px solid #e7dce8}
.hf-beauty-preview--the-bridal-edit{--beauty-paper:#fbf5f0;--beauty-ink:#3b2d2d;--beauty-accent:#b88b61;--beauty-soft:#e9d8d0}
.hf-beauty-preview--the-bridal-edit .hf-beauty-topline{text-align:center;letter-spacing:.28em}
.hf-beauty-preview--the-bridal-edit>header{max-width:1120px;margin:auto;border:0}
.hf-beauty-preview--the-bridal-edit>header strong{font:600 26px "Playfair Display",Georgia,serif}
.hf-beauty-preview--the-bridal-edit .hf-beauty-hero{grid-template-columns:.88fr 1.12fr;padding:36px 7% 60px}
.hf-beauty-preview--the-bridal-edit .hf-beauty-hero h2{font:500 clamp(42px,5vw,68px)/1.02 "Playfair Display",Georgia,serif}
.hf-beauty-preview--the-bridal-edit .hf-beauty-hero-image{min-height:430px;border-radius:48% 48% 4px 4px}
.hf-beauty-preview--the-bridal-edit .hf-beauty-hero-image img{min-height:430px}
.hf-beauty-preview--the-bridal-edit .hf-beauty-service{background:#fffdfa;border:0;border-bottom:1px solid #dfcfc4}
@media(max-width:760px){.hf-beauty-preview>header{align-items:flex-start;flex-direction:column}.hf-beauty-preview>header nav{gap:10px}.hf-beauty-hero,.hf-beauty-preview--the-hair-atelier .hf-beauty-hero,.hf-beauty-preview--the-bridal-edit .hf-beauty-hero{grid-template-columns:1fr;padding:32px 6%;gap:24px}.hf-beauty-hero-image,.hf-beauty-hero-image img{min-height:250px}.hf-beauty-service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hf-beauty-cta{align-items:flex-start;flex-direction:column}.hf-beauty-preview>footer{flex-direction:column}}
@media(max-width:430px){.hf-beauty-service-grid{grid-template-columns:1fr}.hf-beauty-hero h2{font-size:40px}.hf-beauty-service img{aspect-ratio:1.55}}
@media(prefers-reduced-motion:reduce){.hf-beauty-preview *{scroll-behavior:auto!important;transition:none!important;animation:none!important}}

storefront.css:
:root{--sf-primary:#b94f35;--sf-ink:#273b32;--sf-paper:#fbf8f1;--sf-surface:#fff;--sf-accent:#e7a54b;--sf-muted:#77766f;--sf-line:rgba(39,59,50,.14);--sf-font:"DM Sans",sans-serif;--sf-display:"Playfair Display",serif;--sf-radius:18px;color-scheme:light}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--sf-paper);color:var(--sf-ink);font-family:var(--sf-font);font-size:15px;line-height:1.55}button,input,select,textarea{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}button{cursor:pointer}img{display:block;max-width:100%}.sf-loading{min-height:100vh;display:grid;place-content:center;justify-items:center;gap:12px;color:var(--sf-ink)}.sf-loading-mark{display:grid;place-items:center;width:54px;height:54px;border-radius:18px;background:var(--sf-primary);color:#fff;font-weight:900;letter-spacing:.1em}.sf-loading small{color:var(--sf-muted)}.sf-preview-bar{padding:9px 18px;background:#252b35;color:#fff;text-align:center;font-size:11px;letter-spacing:.04em}.sf-preview-bar strong{color:#f4d38b}.sf-announcement{background:var(--sf-ink);color:#fff;padding:8px 4vw;text-align:center;font-size:11px;font-weight:700;letter-spacing:.08em}.sf-header{position:sticky;top:0;z-index:20;background:color-mix(in srgb,var(--sf-paper) 92%,transparent);backdrop-filter:blur(16px);border-bottom:1px solid var(--sf-line)}.sf-header-inner{max-width:1320px;margin:auto;padding:15px 4vw;display:grid;grid-template-columns:auto minmax(180px,1fr) auto;align-items:center;gap:28px}.sf-brand{display:flex;align-items:center;gap:10px;min-width:0}.sf-brand-mark{display:grid;place-items:center;width:40px;height:40px;border-radius:13px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:14px}.sf-brand-copy{display:grid;line-height:1.05}.sf-brand-copy strong{font-family:var(--sf-display);font-size:20px;letter-spacing:-.04em}.sf-brand-copy small{margin-top:5px;color:var(--sf-muted);font-size:9px;letter-spacing:.14em;text-transform:uppercase}.sf-search{display:flex;align-items:center;gap:10px;max-width:550px;width:100%;margin:auto;padding:0 15px;height:44px;background:var(--sf-surface);border:1px solid var(--sf-line);border-radius:999px}.sf-search input{border:0;outline:0;background:transparent;width:100%;min-width:0;color:var(--sf-ink)}.sf-header-actions{display:flex;align-items:center;gap:9px}.sf-icon-btn,.sf-cart-btn,.sf-menu-btn{border:1px solid var(--sf-line);background:var(--sf-surface);color:var(--sf-ink);border-radius:999px;min-height:42px;padding:0 15px;font-weight:800;font-size:12px}.sf-cart-btn{background:var(--sf-primary);border-color:var(--sf-primary);color:#fff}.sf-cart-count{display:inline-grid;place-items:center;min-width:21px;height:21px;margin-left:6px;padding:0 5px;border-radius:99px;background:rgba(255,255,255,.22)}.sf-menu-btn{display:none}.sf-nav{max-width:1320px;margin:auto;padding:0 4vw 12px;display:flex;gap:7px;align-items:center;overflow:auto;scrollbar-width:none}.sf-nav a{white-space:nowrap;padding:7px 12px;border-radius:99px;color:var(--sf-muted);font-size:12px;font-weight:800}.sf-nav a:hover,.sf-nav a[aria-current=page]{background:var(--sf-primary);color:#fff}.sf-main{max-width:1320px;margin:auto;padding:30px 4vw 80px}.sf-page-head{display:flex;align-items:end;justify-content:space-between;gap:24px;margin:10px 0 26px}.sf-kicker{font-size:10px;font-weight:900;letter-spacing:.16em;text-transform:uppercase;color:var(--sf-primary)}.sf-page-head h1{margin:7px 0 6px;font-family:var(--sf-display);font-size:clamp(30px,5vw,54px);line-height:1.02;letter-spacing:-.05em}.sf-page-head p{max-width:680px;margin:0;color:var(--sf-muted)}.sf-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 19px;border:0;border-radius:999px;background:var(--sf-primary);color:#fff;font-weight:900;font-size:13px;transition:transform .2s,box-shadow .2s}.sf-btn:hover{transform:translateY(-2px);box-shadow:0 9px 22px color-mix(in srgb,var(--sf-primary) 22%,transparent)}.sf-btn.secondary{background:var(--sf-surface);border:1px solid var(--sf-line);color:var(--sf-ink)}.sf-btn:disabled{opacity:.45;cursor:not-allowed;transform:none;box-shadow:none}.sf-hero{position:relative;isolation:isolate;display:grid;grid-template-columns:1.05fr .95fr;min-height:420px;overflow:hidden;border-radius:30px;background:var(--sf-ink);color:#fff}.sf-hero-copy{padding:clamp(28px,5vw,66px);display:flex;flex-direction:column;align-items:flex-start;justify-content:center}.sf-hero .sf-kicker{color:var(--sf-accent)}.sf-hero h1{max-width:680px;margin:12px 0 14px;font-family:var(--sf-display);font-size:clamp(36px,5vw,66px);line-height:.98;letter-spacing:-.055em}.sf-hero p{max-width:520px;color:rgba(255,255,255,.75);font-size:15px}.sf-hero-media{position:relative;min-height:320px;background:linear-gradient(135deg,color-mix(in srgb,var(--sf-primary) 70%,#111),var(--sf-accent))}.sf-hero-media img{width:100%;height:100%;object-fit:cover;opacity:.88;mix-blend-mode:luminosity}.sf-hero-badge{position:absolute;right:22px;bottom:22px;padding:14px 18px;border-radius:16px;background:var(--sf-accent);color:#262626;font-size:11px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.sf-section{margin-top:48px}.sf-section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:18px}.sf-section-head h2{margin:4px 0 0;font-family:var(--sf-display);font-size:clamp(24px,3vw,36px);letter-spacing:-.04em}.sf-section-head p{margin:0;color:var(--sf-muted);font-size:13px}.sf-category-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px}.sf-category-tile{min-height:112px;padding:18px;border:1px solid var(--sf-line);border-radius:18px;background:var(--sf-surface);display:flex;flex-direction:column;justify-content:space-between;transition:transform .2s,border-color .2s}.sf-category-tile:hover{transform:translateY(-3px);border-color:var(--sf-primary)}.sf-category-tile span{font-size:24px}.sf-category-tile strong{font-size:13px}.sf-product-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.sf-product-card{min-width:0;border:1px solid var(--sf-line);border-radius:20px;background:var(--sf-surface);overflow:hidden;transition:transform .2s,box-shadow .2s}.sf-product-card:hover{transform:translateY(-4px);box-shadow:0 15px 32px rgba(22,32,26,.09)}.sf-product-media{position:relative;aspect-ratio:1.12;background:linear-gradient(135deg,color-mix(in srgb,var(--sf-primary) 15%,var(--sf-paper)),var(--sf-accent));overflow:hidden}.sf-product-media img{width:100%;height:100%;object-fit:cover}.sf-product-tag{position:absolute;top:12px;left:12px;padding:6px 9px;border-radius:99px;background:var(--sf-accent);color:#282828;font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}.sf-product-info{padding:14px}.sf-product-info small{color:var(--sf-muted);font-size:10px}.sf-product-info h3{margin:4px 0 8px;font-size:14px;line-height:1.35}.sf-product-bottom{display:flex;align-items:center;justify-content:space-between;gap:10px}.sf-price{font-size:15px;font-weight:900;color:var(--sf-primary)}.sf-price del{display:block;color:var(--sf-muted);font-size:10px;font-weight:500}.sf-add{min-height:38px;padding:0 14px;border:0;border-radius:999px;background:var(--sf-primary);color:#fff;font-size:12px;font-weight:800;white-space:nowrap;cursor:pointer;transition:transform .18s ease,opacity .18s ease}.sf-add:hover{transform:translateY(-1px)}.sf-add:disabled{opacity:.45;cursor:not-allowed}.sf-empty{padding:45px 24px;border:1px dashed var(--sf-line);border-radius:22px;background:var(--sf-surface);text-align:center}.sf-empty h3{margin:0 0 8px;font-family:var(--sf-display);font-size:25px}.sf-empty p{margin:0 0 16px;color:var(--sf-muted)}.sf-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:20px 0}.sf-filter-row{display:flex;gap:8px;flex-wrap:wrap}.sf-chip{border:1px solid var(--sf-line);background:var(--sf-surface);color:var(--sf-muted);border-radius:99px;padding:8px 13px;font-size:11px;font-weight:800}.sf-chip.is-active{background:var(--sf-ink);color:#fff;border-color:var(--sf-ink)}.sf-sort{min-height:40px;border:1px solid var(--sf-line);border-radius:12px;background:var(--sf-surface);padding:0 12px;color:var(--sf-ink)}.sf-product-detail{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,5vw,70px);align-items:start}.sf-gallery-main{aspect-ratio:1/1;border-radius:28px;overflow:hidden;background:linear-gradient(135deg,var(--sf-paper),var(--sf-accent))}.sf-gallery-main img{width:100%;height:100%;object-fit:cover}.sf-product-copy{padding:16px 0}.sf-product-copy h1{font-family:var(--sf-display);font-size:clamp(32px,4vw,52px);line-height:1.02;letter-spacing:-.05em;margin:9px 0}.sf-product-copy p{color:var(--sf-muted)}.sf-product-price{font-size:26px;font-weight:900;color:var(--sf-primary)}.sf-qty{display:inline-flex;align-items:center;border:1px solid var(--sf-line);border-radius:99px;overflow:hidden;background:var(--sf-surface)}.sf-qty button{width:42px;height:42px;border:0;background:transparent;font-size:18px}.sf-qty input{width:42px;text-align:center;border:0;background:transparent;font-weight:900}.sf-product-actions{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}.sf-cart-layout,.sf-checkout-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.6fr);gap:24px;align-items:start}.sf-cart-list,.sf-summary,.sf-form-card{border:1px solid var(--sf-line);border-radius:22px;background:var(--sf-surface);padding:20px}.sf-cart-row{display:grid;grid-template-columns:86px minmax(0,1fr) auto;gap:15px;align-items:center;padding:13px 0;border-bottom:1px solid var(--sf-line)}.sf-cart-row:last-child{border-bottom:0}.sf-cart-row img{width:86px;height:86px;object-fit:cover;border-radius:14px;background:var(--sf-paper)}.sf-cart-row h3{margin:0 0 5px;font-size:14px}.sf-cart-row small{color:var(--sf-muted)}.sf-cart-controls{display:flex;align-items:center;gap:8px;margin-top:8px}.sf-cart-controls button{width:28px;height:28px;border:1px solid var(--sf-line);border-radius:50%;background:transparent}.sf-summary h3,.sf-form-card h3{margin:0 0 16px;font-family:var(--sf-display);font-size:24px}.sf-summary-line{display:flex;justify-content:space-between;gap:12px;padding:9px 0;color:var(--sf-muted);font-size:13px}.sf-summary-total{display:flex;justify-content:space-between;padding:15px 0;margin:8px 0;border-top:1px solid var(--sf-line);font-size:18px;font-weight:900}.sf-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.sf-field{display:grid;gap:6px;margin-bottom:13px}.sf-field.full{grid-column:1/-1}.sf-field label{font-size:11px;font-weight:900}.sf-field input,.sf-field textarea,.sf-field select{width:100%;min-height:44px;border:1px solid var(--sf-line);border-radius:11px;padding:10px 12px;background:#fff;color:var(--sf-ink);outline-color:var(--sf-primary)}.sf-field textarea{min-height:100px;resize:vertical}.sf-footer{margin-top:60px;background:var(--sf-ink);color:#fff}.sf-footer-inner{max-width:1320px;margin:auto;padding:42px 4vw 25px;display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px}.sf-footer h3{font-family:var(--sf-display);font-size:22px;margin:0 0 10px}.sf-footer p,.sf-footer a{color:rgba(255,255,255,.68);font-size:12px}.sf-footer-links{display:grid;gap:8px}.sf-footer-bottom{max-width:1320px;margin:auto;padding:16px 4vw;border-top:1px solid rgba(255,255,255,.15);font-size:10px;color:rgba(255,255,255,.55)}.sf-toast{position:fixed;left:50%;bottom:24px;z-index:80;transform:translate(-50%,20px);opacity:0;pointer-events:none;padding:12px 18px;border-radius:99px;background:#202b27;color:#fff;font-size:12px;font-weight:800;box-shadow:0 12px 30px rgba(0,0,0,.2);transition:.25s}.sf-toast.is-visible{transform:translate(-50%,0);opacity:1}.sf-mobile-cart{display:none}.sf-table-wrap{overflow:auto;border:1px solid var(--sf-line);border-radius:18px;background:var(--sf-surface)}.sf-table{width:100%;border-collapse:collapse;min-width:640px}.sf-table th,.sf-table td{padding:14px 16px;border-bottom:1px solid var(--sf-line);text-align:left;font-size:12px}.sf-table th{background:var(--sf-ink);color:#fff;font-size:10px;letter-spacing:.1em}.sf-table td img{width:52px;height:52px;object-fit:cover;border-radius:10px}.sf-status-pill{display:inline-block;padding:6px 10px;border-radius:99px;background:color-mix(in srgb,var(--sf-accent) 30%,white);font-size:10px;font-weight:900;text-transform:uppercase}.sf-timeline{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:24px 0}.sf-timeline span{padding:12px;border-radius:12px;background:var(--sf-surface);border:1px solid var(--sf-line);font-size:11px;text-align:center}.sf-timeline span.is-done{background:var(--sf-primary);color:#fff;border-color:var(--sf-primary)}.sf-content-panel{padding:clamp(22px,4vw,42px);border-radius:24px;background:var(--sf-surface);border:1px solid var(--sf-line)}.sf-content-panel h2{font-family:var(--sf-display);font-size:27px}.sf-content-panel p,.sf-content-panel li{color:var(--sf-muted)}.sf-faq-item{border-bottom:1px solid var(--sf-line);padding:16px 0}.sf-faq-item summary{font-weight:900;cursor:pointer}.sf-faq-item p{color:var(--sf-muted)}.sf-preview-warning{padding:10px 16px;background:#fff3d5;color:#5e481b;text-align:center;font-size:11px;font-weight:800}
body[data-template="fresh-produce"]{--sf-primary:#657c4a;--sf-ink:#293c31;--sf-paper:#f7f7ef;--sf-accent:#d8a65c;--sf-muted:#7c8373;--sf-line:rgba(41,60,49,.16);--sf-font:"DM Sans",sans-serif;--sf-display:"Cormorant Garamond",serif;--sf-radius:28px}
body[data-template="fresh-produce"] .sf-hero{grid-template-columns:.9fr 1.1fr;min-height:500px;background:#e8eddf;color:#293c31;border-radius:4px 120px 4px 4px}
body[data-template="fresh-produce"] .sf-hero-copy{padding-left:clamp(32px,7vw,90px)}
body[data-template="fresh-produce"] .sf-hero p{color:#64715f}
body[data-template="fresh-produce"] .sf-hero-media img{mix-blend-mode:normal;opacity:1}
body[data-template="fresh-produce"] .sf-category-tile{border-radius:4px 26px 4px 4px;background:#fffefa}
body[data-template="fresh-produce"] .sf-product-card{border-radius:4px 28px 4px 4px;box-shadow:none}
body[data-template="fresh-produce"] .sf-product-media{aspect-ratio:1/1.08}
body[data-template="express-grocery"]{--sf-primary:#df6b35;--sf-ink:#27354a;--sf-paper:#f7f8fb;--sf-accent:#f3c54b;--sf-muted:#768194;--sf-line:rgba(39,53,74,.14);--sf-font:"Inter",sans-serif;--sf-display:"Manrope",sans-serif}
body[data-template="express-grocery"] .sf-announcement{background:#df6b35;color:#fff}
body[data-template="express-grocery"] .sf-hero{min-height:340px;border-radius:24px;background:#27354a}
body[data-template="express-grocery"] .sf-hero h1{font-family:"Manrope",sans-serif;font-weight:800}
body[data-template="express-grocery"] .sf-category-tile{min-height:92px;border-radius:14px;border-bottom:4px solid var(--sf-accent)}
body[data-template="express-grocery"] .sf-product-card{border-radius:14px}
body[data-template="express-grocery"] .sf-product-info{padding:11px}
body[data-template="express-grocery"] .sf-product-info h3{font-size:12px}
body[data-template="wholesale-bulk"]{--sf-primary:#344b70;--sf-ink:#25344b;--sf-paper:#f5f7fa;--sf-accent:#d4a85a;--sf-muted:#738094;--sf-line:rgba(37,52,75,.16);--sf-font:"Inter",sans-serif;--sf-display:"IBM Plex Sans",sans-serif}
body[data-template="wholesale-bulk"] .sf-announcement{background:#d4a85a;color:#26364e}
body[data-template="wholesale-bulk"] .sf-hero{border-radius:10px;min-height:390px;background:#25344b}
body[data-template="wholesale-bulk"] .sf-hero h1{font-family:"IBM Plex Sans",sans-serif;font-weight:700}
body[data-template="wholesale-bulk"] .sf-category-tile{border-radius:8px;border-top:3px solid var(--sf-accent)}
body[data-template="wholesale-bulk"] .sf-product-card{border-radius:8px}
body[data-template="wholesale-bulk"] .sf-product-info h3{font-family:"IBM Plex Sans",sans-serif}
@media(max-width:1000px){.sf-category-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.sf-product-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.sf-header-inner{grid-template-columns:auto 1fr auto;gap:14px}.sf-footer-inner{grid-template-columns:1.3fr 1fr 1fr}.sf-footer-inner>div:last-child{grid-column:2/-1}}
@media(max-width:720px){.sf-header-inner{grid-template-columns:auto 1fr auto;padding:11px 16px;gap:9px}.sf-brand-mark{width:36px;height:36px}.sf-brand-copy strong{font-size:16px}.sf-brand-copy small{font-size:8px}.sf-header-inner>.sf-search{grid-column:1/-1;grid-row:2;max-width:none;order:3;height:40px}.sf-header-actions{gap:5px}.sf-icon-btn{display:none}.sf-cart-btn{padding:0 11px;min-height:38px;font-size:11px}.sf-menu-btn{display:inline-flex;align-items:center;justify-content:center;padding:0 11px;min-height:38px}.sf-nav{display:none;padding:8px 16px 12px;flex-wrap:wrap;overflow:visible}.sf-nav.is-open{display:flex}.sf-nav a{padding:8px 11px;background:var(--sf-surface);border:1px solid var(--sf-line)}.sf-main{padding:20px 16px 92px}.sf-page-head{display:block;margin:5px 0 20px}.sf-page-head .sf-btn{margin-top:14px}.sf-hero,.sf-hero[data-layout]{grid-template-columns:1fr;min-height:0;border-radius:22px}.sf-hero-copy{padding:30px 24px}.sf-hero h1{font-size:clamp(34px,10vw,48px)}.sf-hero-media{min-height:220px;max-height:260px}.sf-hero-badge{right:12px;bottom:12px}.sf-section{margin-top:34px}.sf-category-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.sf-category-tile{min-height:92px;padding:13px}.sf-product-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.sf-product-info{padding:11px}.sf-product-info h3{font-size:12px}.sf-product-bottom{gap:5px}.sf-price{font-size:13px}.sf-add{width:32px;height:32px}.sf-toolbar{align-items:flex-start;flex-direction:column}.sf-product-detail,.sf-cart-layout,.sf-checkout-layout{grid-template-columns:1fr}.sf-gallery-main{max-height:440px}.sf-product-copy{padding:0}.sf-cart-list,.sf-summary,.sf-form-card{padding:15px}.sf-cart-row{grid-template-columns:66px minmax(0,1fr);gap:11px}.sf-cart-row>div:last-child{grid-column:2}.sf-cart-row img{width:66px;height:66px}.sf-form-grid{grid-template-columns:1fr}.sf-field.full{grid-column:auto}.sf-footer-inner{grid-template-columns:1fr 1fr;padding:30px 18px 20px;gap:22px}.sf-footer-inner>div:first-child{grid-column:1/-1}.sf-footer-inner>div:last-child{grid-column:auto}.sf-footer-bottom{padding:14px 18px}.sf-mobile-cart{display:flex;position:fixed;left:12px;right:12px;bottom:12px;z-index:30;align-items:center;justify-content:space-between;padding:10px 12px 10px 16px;border-radius:16px;background:var(--sf-ink);color:#fff;box-shadow:0 12px 32px rgba(0,0,0,.2)}.sf-mobile-cart span{font-size:11px;color:rgba(255,255,255,.7)}.sf-mobile-cart strong{font-size:13px}.sf-mobile-cart .sf-btn{min-height:38px;background:var(--sf-accent);color:#252525}.sf-timeline{grid-template-columns:repeat(2,1fr)}.sf-preview-bar{font-size:10px}.sf-page-head h1{font-size:36px}}
@media(max-width:420px){.sf-brand-copy small{display:none}.sf-brand-copy strong{font-size:15px}.sf-header-inner{gap:7px}.sf-cart-btn{padding:0 8px}.sf-product-grid{gap:8px}.sf-product-info{padding:9px}.sf-product-info h3{font-size:11px}.sf-price{font-size:12px}.sf-section-head h2{font-size:24px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}

/* Editorial content and blog system */
.sf-rich-content{display:grid;gap:22px;line-height:1.75}
.sf-rich-block{padding:0 0 20px;border-bottom:1px solid var(--sf-line)}
.sf-rich-block:last-child{padding-bottom:0;border-bottom:0}
.sf-rich-block h2{margin:0 0 10px;font-family:var(--sf-display);font-size:clamp(21px,2.4vw,30px);letter-spacing:-.025em}
.sf-rich-block p{max-width:850px;margin:8px 0;color:var(--sf-muted);line-height:1.8}
.sf-rich-block ul{margin:10px 0;padding-left:22px;color:var(--sf-muted);line-height:1.9}
.sf-rich-cta{padding-top:10px}
.sf-blog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.sf-blog-card{overflow:hidden;border:1px solid var(--sf-line);border-radius:var(--sf-radius);background:var(--sf-surface);box-shadow:0 12px 30px rgba(28,38,32,.045)}
.sf-blog-card>a:first-child{display:block;overflow:hidden;background:var(--sf-paper)}
.sf-blog-card img{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;transition:transform .35s ease}
.sf-blog-card:hover img{transform:scale(1.035)}
.sf-blog-card-body{padding:20px}
.sf-blog-card h2{margin:9px 0;font-family:var(--sf-display);font-size:clamp(20px,2.3vw,28px);line-height:1.14;letter-spacing:-.025em}
.sf-blog-card h2 a{color:var(--sf-ink);text-decoration:none}
.sf-blog-card p{color:var(--sf-muted);font-size:13px;line-height:1.75}
.sf-blog-meta{color:var(--sf-primary);font-size:10px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}
