body[data-template="clinic-medical-supplies"]{--sf-primary:#285e8c;--sf-ink:#18334d;--sf-paper:#f2f6fa;--sf-line:#d7e2ec;--sf-surface:#fff}
body[data-template="express-medicine-delivery"]{--sf-primary:#e87537;--sf-ink:#302b29;--sf-paper:#fff7f0;--sf-line:#f0dfd2;--sf-surface:#fff}
.sf-pharmacy-modern-hero,.sf-wellness-hero,.sf-clinic-hero,.sf-express-hero{max-width:1320px;margin:24px auto 0;overflow:hidden}
.sf-pharmacy-modern-hero{display:grid;grid-template-columns:1.05fr .95fr;min-height:520px;background:#e7f2ef;border-radius:28px}
.sf-pharmacy-modern-copy{display:flex;flex-direction:column;justify-content:center;padding:clamp(30px,5vw,76px)}
.sf-pharmacy-modern-copy h1,.sf-wellness-copy h1,.sf-clinic-copy h1,.sf-express-copy h1{font-family:var(--sf-display);font-size:clamp(38px,5.2vw,68px);line-height:.99;letter-spacing:-.055em;margin:18px 0}
.sf-pharmacy-modern-copy p,.sf-wellness-copy p,.sf-clinic-copy p,.sf-express-copy p{max-width:560px;color:#5e706d;line-height:1.8;font-size:15px}
.sf-pharmacy-modern-actions,.sf-clinic-actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:22px}
.sf-text-link{font-size:13px;font-weight:800;text-decoration:underline;text-underline-offset:5px}
.sf-pharmacy-modern-proof{display:flex;gap:18px;flex-wrap:wrap;margin-top:40px;padding-top:20px;border-top:1px solid #c7dcd6}
.sf-pharmacy-modern-proof span{display:grid;gap:5px;font-size:10px;color:#72847f}.sf-pharmacy-modern-proof b{font-size:12px;color:#234b4a}
.sf-pharmacy-modern-image,.sf-wellness-image,.sf-clinic-image,.sf-express-image{position:relative;min-height:380px;overflow:hidden}
.sf-pharmacy-modern-image>img,.sf-wellness-image>img,.sf-clinic-image>img,.sf-express-image>img{width:100%;height:100%;position:absolute;inset:0;object-fit:cover}
.sf-pharmacy-image-note{position:absolute;left:22px;bottom:22px;display:grid;grid-template-columns:40px 1fr;column-gap:12px;align-items:center;padding:15px 20px;background:#fff;border-radius:16px;box-shadow:0 15px 40px #183b421c}
.sf-pharmacy-image-note>span{grid-row:span 2;width:40px;height:40px;display:grid;place-items:center;background:#e5f3ef;border-radius:50%;color:#137f79;font-size:22px}
.sf-pharmacy-image-note b{font-size:13px}.sf-pharmacy-image-note small{color:#71817b;font-size:10px}
.sf-pharmacy-trustline{display:flex;justify-content:center;gap:clamp(14px,4vw,54px);flex-wrap:wrap;padding:20px 4%;font-size:10px;font-weight:800;letter-spacing:.1em;color:#617773;border-bottom:1px solid var(--sf-line)}
.sf-pharmacy-departments{padding-top:40px;padding-bottom:18px}
.sf-pharmacy-department-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.sf-pharmacy-department{min-height:118px;padding:18px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid var(--sf-line);border-radius:16px;background:var(--sf-surface);transition:transform .2s,box-shadow .2s}
.sf-pharmacy-department:hover{transform:translateY(-3px);box-shadow:0 12px 28px #1b35400d}
.sf-pharmacy-department span,.sf-pharmacy-department small{font-size:10px;color:var(--sf-muted)}.sf-pharmacy-department strong{font-size:18px;color:var(--sf-ink)}
.sf-pharmacy-modern-support,.sf-clinic-quote,.sf-express-basket-cta{max-width:1200px;margin:36px auto 48px;padding:clamp(24px,4vw,44px);display:flex;align-items:center;justify-content:space-between;gap:24px;border-radius:22px;background:#173f43;color:#fff}
.sf-pharmacy-modern-support h2,.sf-clinic-quote h2,.sf-express-basket-cta h2{font-family:var(--sf-display);font-size:clamp(28px,3.8vw,46px);line-height:1.04;margin:10px 0}
.sf-pharmacy-modern-support p,.sf-clinic-quote p,.sf-express-basket-cta p{max-width:650px;color:#d0e0dc;line-height:1.7}
.sf-pharmacy-modern-support .sf-kicker,.sf-clinic-quote .sf-kicker,.sf-express-basket-cta .sf-kicker{color:#a8d7cb}
.sf-pharmacy-modern-support .sf-btn,.sf-clinic-quote .sf-btn,.sf-express-basket-cta .sf-btn{background:#fff;color:#173f43;white-space:nowrap}
.sf-wellness-hero{display:grid;grid-template-columns:1.15fr .85fr;min-height:560px;background:#efeee5}
.sf-wellness-image{min-height:560px}
.sf-wellness-image:after{content:"";position:absolute;inset:35% 0 0;background:linear-gradient(0deg,#1e2c1d9c,transparent)}
.sf-wellness-image>span{position:absolute;z-index:1;left:28px;bottom:28px;color:#fff;font-size:11px;font-weight:900;letter-spacing:.16em}
.sf-wellness-copy{align-self:center;padding:clamp(28px,4.5vw,64px)}
.sf-wellness-copy h1{font-family:Georgia,serif;font-weight:500;color:#344536}
.sf-wellness-copy>small{display:block;margin-top:26px;color:#79816c;font-size:11px;letter-spacing:.08em}
.sf-wellness-values{display:flex;justify-content:center;gap:34px;flex-wrap:wrap;padding:22px 4%;background:#e5e5d8;color:#52624b;font-size:11px;font-weight:800}
.sf-wellness-story{max-width:1200px;margin:50px auto;display:grid;grid-template-columns:.9fr 1.1fr;gap:42px;align-items:center;padding:0 4%}
.sf-wellness-story h2{font-family:Georgia,serif;font-size:clamp(34px,4vw,54px);font-weight:500;line-height:1.06;color:#344536}
.sf-wellness-story p{line-height:1.8;color:#687264}.sf-wellness-story a{font-weight:800;color:#61774e}
.sf-wellness-story img{width:100%;height:380px;object-fit:cover;border-radius:48% 48% 12px 12px}
.sf-wellness-guide-strip{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:28px 5%;background:#f0efe6}
.sf-wellness-guide-strip h2{font-family:Georgia,serif;font-size:clamp(26px,3vw,40px);font-weight:500;margin:8px 0}
.sf-wellness-guide-strip p{color:#6e7869}
.sf-clinic-hero{display:grid;grid-template-columns:1.08fr .92fr;min-height:520px;background:#e8eff6;border:1px solid #d6e2ec}
.sf-clinic-copy{padding:clamp(30px,4.5vw,64px);align-self:center}
.sf-clinic-copy h1{color:#18334d}
.sf-clinic-copy p{color:#60758a}
.sf-clinic-actions .sf-btn.secondary{background:#fff;color:#285e8c;border:1px solid #c7d8e7}
.sf-clinic-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:38px;padding-top:20px;border-top:1px solid #c8d7e4}
.sf-clinic-metrics span{display:grid;gap:7px;font-size:10px;color:#5b7185}.sf-clinic-metrics b{font-size:18px;color:#285e8c}
.sf-clinic-image>div{position:absolute;left:20px;right:20px;bottom:20px;padding:16px 18px;background:#17334c;color:#fff;display:grid;gap:5px}
.sf-clinic-image small{color:#bfd4e5;font-size:10px;letter-spacing:.12em}
.sf-clinic-process{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:17px 4%;background:#17334c;color:#d7e5ef;font-size:10px;font-weight:800;letter-spacing:.08em}
.sf-clinic-quote{background:#17334c}
.sf-clinic-quote .sf-btn{color:#17334c}
.sf-express-hero{display:grid;grid-template-columns:1.1fr .9fr;min-height:420px;background:#fff1e5;border-radius:24px}
.sf-express-copy{padding:clamp(28px,4.5vw,60px);align-self:center}
.sf-express-copy h1{color:#302b29}
.sf-express-copy p{color:#70645d}
.sf-express-image{min-height:420px}
.sf-express-delivery-note{display:flex;gap:12px;align-items:center;margin-top:28px;padding:14px 16px;border:1px solid #f0d6c3;border-radius:14px;background:#fffaf5;max-width:440px}
.sf-express-delivery-note>span{font-size:24px;color:#e87537}.sf-express-delivery-note div{display:grid;gap:4px}.sf-express-delivery-note b{font-size:12px}.sf-express-delivery-note small{font-size:10px;color:#85766d;line-height:1.5}
.sf-express-steps{display:flex;justify-content:center;gap:clamp(16px,4vw,48px);flex-wrap:wrap;padding:17px 4%;background:#302b29;color:#fff;font-size:11px;font-weight:800}
.sf-express-basket-cta{background:#302b29}.sf-express-basket-cta .sf-kicker{color:#ffc49f}.sf-express-basket-cta .sf-btn{color:#302b29}
.sf-pharmacy-safety{max-width:1200px}
@media(max-width:760px){
 .sf-pharmacy-modern-hero,.sf-wellness-hero,.sf-clinic-hero,.sf-express-hero{grid-template-columns:1fr;margin:12px 4vw;border-radius:18px}
 .sf-pharmacy-modern-copy,.sf-wellness-copy,.sf-clinic-copy,.sf-express-copy{padding:28px 22px}
 .sf-pharmacy-modern-image,.sf-wellness-image,.sf-clinic-image,.sf-express-image{min-height:270px}
 .sf-pharmacy-modern-proof{gap:12px;margin-top:24px}
 .sf-pharmacy-department-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .sf-pharmacy-trustline{justify-content:flex-start;font-size:9px}
 .sf-wellness-image{grid-row:1}.sf-wellness-story{grid-template-columns:1fr;margin:30px auto;gap:18px}
 .sf-wellness-story img{height:260px;border-radius:24px}
 .sf-wellness-guide-strip,.sf-pharmacy-modern-support,.sf-clinic-quote,.sf-express-basket-cta{align-items:flex-start;flex-direction:column;margin:24px 4vw}
 .sf-clinic-metrics{grid-template-columns:1fr}
}
@media(prefers-reduced-motion:reduce){.sf-pharmacy-department,.sf-pharmacy-modern-image img{transition:none!important}}
.sf-health-hero{display:grid;grid-template-columns:1fr 1fr;gap:30px;padding:48px 5%;align-items:center;background:#f3f8fa}.sf-health-hero h1{font:500 clamp(34px,5vw,58px)/1.05 Georgia,serif;color:var(--sf-ink)}.sf-health-hero p{line-height:1.8;color:#607584}.sf-health-photo{position:relative}.sf-health-photo img{width:100%;height:300px;object-fit:cover;border-radius:16px}.sf-health-photo small{display:block;font-size:9px;color:#647684}.sf-health-link{font-size:12px;font-weight:800;color:var(--sf-primary);margin-left:12px}.sf-health-promise{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.sf-health-promise span{padding:7px 10px;background:#fff;border:1px solid #d8e5ea;border-radius:20px;font-size:10px}.sf-health-quick{display:grid;grid-template-columns:repeat(4,1fr);background:#fff;border-block:1px solid #d8e5ea}.sf-health-quick a{padding:16px;font-size:11px;font-weight:800}.sf-health-section{padding:40px 5%}.sf-health-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin:20px 0}.sf-health-card{padding:20px;background:#fff;border:1px solid #d8e5ea;border-radius:12px}.sf-health-card h3{font-size:16px}.sf-health-card p{font-size:12px;line-height:1.6;color:#647684}.sf-health-card b,.sf-health-card a{font-size:11px;color:var(--sf-primary)}.sf-health-provider,.sf-health-safety{padding:28px 5%;background:#17384f;color:#fff}.sf-health-provider p{color:#d1e0e6}.sf-health-provider a{color:#b9e4e7}.sf-health-safety{background:#e8f0f3;color:#536b79;font-size:11px;line-height:1.7}.sf-health-content,.sf-health-booking{max-width:1000px;margin:24px auto;padding:24px;background:#fff;border:1px solid #d8e5ea;border-radius:12px}.sf-health-content p{line-height:1.7;color:#647684}.sf-health-booking{display:grid;grid-template-columns:.8fr 1.2fr;gap:22px}.sf-health-booking form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sf-health-booking label{display:grid;gap:6px;font-size:11px;font-weight:700}.sf-health-booking input,.sf-health-booking select,.sf-health-booking textarea{padding:11px;border:1px solid #d8e5ea;border-radius:7px}.sf-health-wide{grid-column:1/-1}.sf-health-emergency{padding:24px;background:#fff1ed;border-left:5px solid #b84d36}.sf-health-footer{background:#17384f;color:#fff}.sf-health-footer .sf-footer-inner{padding:30px 5%}.sf-health-footer a,.sf-health-footer p{color:#d1e0e6}.sf-health-footer-note{padding:14px 5%;font-size:10px;border-top:1px solid #ffffff30}@media(max-width:760px){.sf-health-hero,.sf-health-booking{grid-template-columns:1fr;padding:25px 16px}.sf-health-quick{grid-template-columns:1fr 1fr}.sf-health-grid,.sf-health-booking form{grid-template-columns:1fr}.sf-health-section{padding:28px 16px}}.sf-health-resource-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;max-width:1100px;margin:26px auto}.sf-health-resource-card{display:grid;gap:9px;padding:21px;background:#fff;border:1px solid #d8e5ea;border-radius:12px;text-decoration:none;color:var(--sf-ink)}.sf-health-resource-card small{font-size:9px;letter-spacing:.1em;color:var(--sf-primary);font-weight:900}.sf-health-resource-card h3{margin:0;font-size:16px}.sf-health-resource-card p{margin:0;color:#647684;font-size:12px;line-height:1.6}.sf-health-resource-card b{font-size:11px;color:var(--sf-primary)}.sf-health-article{max-width:850px}.sf-health-article h2{margin-top:24px}@media(max-width:760px){.sf-health-resource-grid{grid-template-columns:1fr;margin:18px;padding:0 16px}}
/* Healthcare editorial image distribution: page-level imagery, never a photo-wall. */
.sf-health-card{overflow:hidden;padding:0;text-decoration:none;color:inherit}
.sf-health-card-image{display:block;width:100%;height:170px;object-fit:cover;border-radius:10px 10px 0 0;pointer-events:none}
.sf-health-card>small,.sf-health-card>h3,.sf-health-card>p,.sf-health-card>b{display:block;margin-left:18px;margin-right:18px}
.sf-health-card>small{margin-top:16px}
.sf-health-card>b{margin-bottom:18px}
.sf-health-media-section{max-width:1120px;margin:34px auto 58px;padding:0 22px}
.sf-health-media-heading{margin:0 0 22px}
.sf-health-media-heading>small,.sf-health-media-copy>small{font-size:10px;letter-spacing:.14em;font-weight:800;color:var(--sf-primary)}
.sf-health-media-heading h2{font-size:clamp(24px,3vw,34px);margin:7px 0}
.sf-health-media-heading p{font-size:13px;color:#647684}
.sf-health-media-story{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(240px,.9fr);gap:clamp(20px,4vw,48px);align-items:center;padding:22px 0;border-top:1px solid #d8e5ea}
.sf-health-media-story.is-reversed .sf-health-media-image{order:2}
.sf-health-media-image img{display:block;width:100%;height:clamp(190px,25vw,300px);object-fit:cover;border-radius:14px;pointer-events:none}
.sf-health-media-copy h3{font:500 clamp(20px,2.5vw,28px)/1.2 Georgia,serif;color:var(--sf-ink);margin:9px 0}
.sf-health-media-copy p{font-size:13px;line-height:1.8;color:#647684}
.sf-health-media-section img{-webkit-user-drag:none;user-select:none}
@media(max-width:760px){.sf-health-media-story{grid-template-columns:1fr;gap:12px;padding:16px 0}.sf-health-media-story.is-reversed .sf-health-media-image{order:0}.sf-health-media-image img{height:220px}.sf-health-card-image{height:150px}}
\n/* Healthcare image links remain internal and preserve the editorial image layout. */\n.sf-health-photo-link,.sf-health-image-link{display:block;color:inherit;text-decoration:none;cursor:pointer}.sf-health-photo-link:focus-visible,.sf-health-image-link:focus-visible{outline:3px solid var(--sf-primary);outline-offset:4px;border-radius:14px}.sf-health-image-link img{pointer-events:none}\n

/* Real Estate & Property — four distinct editorial systems */
.sf-realestate{--re-ink:#1e2d34;--re-accent:#a98755;--re-paper:#f6f3ed;--re-soft:#e9e0d3;--re-line:rgba(30,45,52,.14);color:var(--re-ink);background:var(--re-paper);padding:clamp(18px,3vw,42px);font-family:inherit}
.sf-realestate--estate-luxe{--re-ink:#1e2d34;--re-accent:#a98755;--re-paper:#f6f3ed;--re-soft:#e9e0d3}
.sf-realestate--nestliving-rentals{--re-ink:#294139;--re-accent:#b66d52;--re-paper:#f8f4ee;--re-soft:#e7e8dc}
.sf-realestate--urbanaxis-commercial{--re-ink:#1d3040;--re-accent:#3e7189;--re-paper:#f1f5f7;--re-soft:#dce7ec}
.sf-realestate--horizon-developments{--re-ink:#263a35;--re-accent:#a66b49;--re-paper:#f4f3ef;--re-soft:#e1e8e1}
.sf-realestate h1,.sf-realestate h2,.sf-realestate h3{color:var(--re-ink);letter-spacing:-.035em}
.sf-realestate a{color:inherit;text-decoration:none}
.sf-realestate img{display:block;width:100%;height:100%;object-fit:cover}
.sf-re-hero{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,1.05fr);gap:clamp(28px,5vw,76px);align-items:center;max-width:1440px;margin:0 auto;padding:clamp(24px,4vw,56px) 0 34px}
.sf-re-hero-copy>small,.sf-re-section small,.sf-re-services small,.sf-re-cta small{display:block;color:var(--re-accent);font-size:10px;font-weight:800;letter-spacing:.19em;text-transform:uppercase}
.sf-re-hero h1{font-family:Georgia,serif;font-size:clamp(42px,6vw,82px);line-height:1.02;font-weight:500;max-width:720px;margin:18px 0}
.sf-re-hero-copy>p{font-size:clamp(15px,1.5vw,18px);line-height:1.8;color:#68747a;max-width:560px}
.sf-re-hero-media{position:relative;min-height:420px;overflow:hidden;background:var(--re-soft);border-radius:4px}
.sf-re-hero-media>a{display:block;height:100%;min-height:420px}
.sf-re-hero-media img{position:absolute;inset:0}
.sf-re-hero-media>span{position:absolute;bottom:18px;left:20px;padding:8px 12px;background:rgba(255,255,255,.88);font-size:9px;letter-spacing:.12em;font-weight:800}
.sf-re-trust{display:flex;flex-wrap:wrap;gap:10px 18px;margin-top:26px;color:#65716f;font-size:12px}
.sf-re-search{max-width:1180px;margin:12px auto 56px;padding:18px;display:grid;grid-template-columns:1.2fr 1fr auto;gap:14px;align-items:end;background:#fff;border:1px solid var(--re-line);box-shadow:0 18px 50px rgba(30,45,52,.07)}
.sf-re-search label,.sf-re-listing-tools label,.sf-re-enquiry-form label{display:grid;gap:8px;color:#68747a;font-size:11px;font-weight:700}
.sf-re-search input,.sf-re-search select,.sf-re-listing-tools input,.sf-re-listing-tools select,.sf-re-enquiry-form input,.sf-re-enquiry-form select,.sf-re-enquiry-form textarea{width:100%;min-height:46px;padding:12px 14px;border:1px solid var(--re-line);border-radius:2px;background:#fff;color:var(--re-ink);font:inherit}
.sf-realestate .sf-btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 20px;border:0;border-radius:2px;background:var(--re-ink);color:#fff;font-size:12px;font-weight:800;letter-spacing:.02em}
.sf-realestate .sf-btn.secondary{background:var(--re-soft);color:var(--re-ink)}
.sf-re-section,.sf-re-services,.sf-re-cta{max-width:1440px;margin:0 auto 64px}
.sf-re-section-head{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:24px}
.sf-re-section-head h2,.sf-re-services h2,.sf-re-cta h2{font-family:Georgia,serif;font-size:clamp(30px,4vw,52px);font-weight:500;margin:10px 0}
.sf-re-section-head p,.sf-re-services p,.sf-re-cta p{color:#68747a;line-height:1.7}
.sf-re-home-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.sf-re-home-card{background:#fff;border:1px solid var(--re-line);min-width:0}
.sf-re-home-card .sf-re-image-link{display:block;height:210px;overflow:hidden;background:var(--re-soft)}
.sf-re-home-card>div{padding:17px}
.sf-re-home-card small,.sf-re-listing-card small,.sf-re-detail-copy small{color:var(--re-accent);font-size:9px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}
.sf-re-home-card h3{font-family:Georgia,serif;font-size:21px;font-weight:500;margin:9px 0}
.sf-re-home-card p{color:#68747a;font-size:12px}
.sf-re-home-card b{display:block;margin:12px 0;font-size:13px}
.sf-re-home-card>div>a,.sf-re-listing-card>div>a,.sf-re-editorial-story>div>a,.sf-re-text-link{display:inline-block;margin-top:10px;color:var(--re-accent);font-size:12px;font-weight:800}
.sf-re-services{display:grid;grid-template-columns:.8fr 1.2fr;gap:40px;padding:34px 0;border-top:1px solid var(--re-line);border-bottom:1px solid var(--re-line)}
.sf-re-services>div:last-child{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.sf-re-services>div:last-child>a{display:grid;grid-template-columns:36px 1fr;gap:7px 12px;padding:20px;background:#fff;border:1px solid var(--re-line)}
.sf-re-services>div:last-child>a>b{grid-row:span 2;color:var(--re-accent)}
.sf-re-services>div:last-child>a>strong{font-family:Georgia,serif;font-size:18px;font-weight:500}
.sf-re-services>div:last-child>a>span{color:#68747a;font-size:12px;line-height:1.6}
