function pageUrl(page,extra={}){const p=new URLSearchParams({site:siteSlug,page,...extra});if(preview)p.set("preview","1");const base=siteConfig.basePath||(location.pathname.endsWith("/storefront.html")?location.pathname:"./");return base+"?"+p.toString();}
