function cartCount(){return state.cart.reduce((n,x)=>n+Number(x.quantity||0),0);}
function priceForProduct(p,quantity=1){if(!p)return 0;const tiers=state.priceTiers.filter(t=>t.product_id===p.id&&Number(t.minimum_quantity)<=Number(quantity)).sort((a,b)=>Number(b.minimum_quantity)-Number(a.minimum_quantity));return Number(tiers[0]?.unit_price??p.price);}
