function updateCheckoutSummary(){const area=root.querySelector("#sfArea")?.value||"";state.checkoutArea=area;const fee=deliveryFeeForArea(area),total=cartTotal(),minimum=minimumOrderForArea(area),feeNode=root.querySelector("[data-summary-delivery]"),totalNode=root.querySelector("[data-summary-total]"),note=root.querySelector("[data-summary-note]"),button=root.querySelector("#sfPlaceOrder");if(feeNode)feeNode.textContent=money(fee);if(totalNode)totalNode.textContent=money(total+fee);const eta=deliveryZoneForArea(area)?.eta_label;if(note)note.textContent=minimum>0&&total<minimum?"Minimum order is "+money(minimum)+". Add "+money(minimum-total)+" more to continue.":"Delivery fee uses the selected delivery zone when available; otherwise the store default applies."+(eta?" Estimated delivery: "+eta+".":"");if(button)button.disabled=total<minimum;}
