async function submitPropertyEnquiry(e){
 e.preventDefault();const form=e.currentTarget,data=new FormData(form),status=root.querySelector("#sfPropertyEnquiryStatus"),button=form.querySelector('button[type="submit"]');
 if(state.website.settings?.showcase_mode){status.textContent="Template showcase only. Property enquiries are disabled; no information was sent.";return;}
 if(preview){status.textContent="Private preview only. No enquiry was sent.";return;}
 const name=String(data.get("name")||"").trim(),phone=String(data.get("phone")||"").trim();
 if(!name||!phone||!data.get("consent")){status.textContent="Enter your name and phone number and accept the contact consent.";return;}
 button.disabled=true;button.textContent="Sending enquiry…";
