  const interest=String(data.get("interest")||"Property enquiry"),message=String(data.get("message")||"").trim(),date=String(data.get("preferred_date")||"").trim();
  const business={company_name:"Property enquiry — "+(state.website.brand?.name||state.website.name),contact_name:name,phone,email:String(data.get("email")||"").trim(),business_type:"real-estate-property"};
  const items=[{description:interest,quantity:1,preferred_date:date,property_reference:params.get("listing")||"",page:state.page}];
  const notes=("Property enquiry. Interest: "+interest+". Preferred date: "+date+". Requirements: "+message).slice(0,2000);
  const result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,notes);
  status.textContent=(result?.message||"Your property enquiry has been received.")+" Reference: "+(result?.quote_number||"saved")+". The property team will confirm the next step.";form.reset();
 }catch(err){status.textContent=err.message||"Your enquiry could not be sent. Please try again or contact the property team.";}
 finally{button.disabled=false;button.textContent="Send property enquiry ↗";}
}
