function healthcarePageImages(key,count=4){
 const limit=key==="home"?5:4;
 const page=state.pages.find(p=>p.page_key===key),media=page?.page_spec?.media||{};
 const fromPage=Array.isArray(media.images)?media.images.filter(row=>row&&row.id&&row.src):[];
 const pool=[],seen=new Set();
 for(const p of state.pages){const m=p.page_spec?.media||{},rows=Array.isArray(m.images)?m.images:[];for(const row of rows){if(row?.id&&row?.src&&!seen.has(String(row.id))){seen.add(String(row.id));pool.push(row);}}}
 for(const p of state.pages){const ids=p.page_spec?.media?.imageAssetIds||[];for(const id of ids){if(!seen.has(String(id))){seen.add(String(id));pool.push({id:String(id),src:"https://images.pexels.com/photos/"+encodeURIComponent(id)+"/pexels-photo-"+encodeURIComponent(id)+".jpeg?auto=compress&cs=tinysrgb&w=1400",alt:"Illustrative healthcare photography"});}}}
 const selected=[],add=x=>{if(x?.id&&x?.src&&!selected.some(y=>String(y.id)===String(x.id)))selected.push(x);};
 fromPage.forEach(add);
 (media.imageAssetIds||[]).forEach(id=>add(pool.find(x=>String(x.id)===String(id))));
 const seed=[...String(key)].reduce((n,c)=>n+c.charCodeAt(0),0);
 let i=seed%Math.max(1,pool.length),guard=0;
 while(selected.length<limit&&guard<pool.length*2){add(pool[i%pool.length]);i++;guard++;}
 return selected.slice(0,limit);
}
